import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3, mul } from 'three/tsl';

export default function createNode(config, ctx) {
  const { PlaneGeometry, Mesh, Group } = ctx.THREE;

  const group = new Group();
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Load the feature card texture
  let textureResource = null;
  const loadTexture = () => {
    return ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        textureResource = tex;
        // Create plane with loaded texture
        const geometry = new PlaneGeometry(3.5, 2.2);
        const material = new MeshBasicNodeMaterial();

        // Set up texture node with UV mapping
        const texNode = texture(tex, uv());
        material.colorNode = texNode;

        const mesh = new Mesh(geometry, material);
        mesh.renderOrder = 10;
        group.add(mesh);

        return mesh;
      })
      .catch((err) => {
        console.error('Failed to load feature card texture:', err);
        // Fallback: create a plane with a surface color
        const geometry = new PlaneGeometry(3.5, 2.2);
        const material = new MeshBasicNodeMaterial({
          color: 0x0b0b10,
        });
        const mesh = new Mesh(geometry, material);
        mesh.renderOrder = 10;
        group.add(mesh);
        return mesh;
      });
  };

  // Trigger async load
  loadTexture();

  // Cleanup handler
  group.userData.cleanup = () => {
    group.traverse((child) => {
      if (child.geometry) {
        child.geometry.dispose();
      }
      if (child.material) {
        child.material.dispose();
      }
    });
    if (textureResource) {
      textureResource.dispose();
    }
  };

  group.userData.handlers = {};

  return group;
}
